for (const item of $input.all()) {
  // Corrigido: "Nome" com inicial maiúscula
  const nome = item.json.Nome.trim();

  // Corrigido: "telefone" com base na chave exata
  const telefone = item.json.telefone.replace(/[()\-\s]/g, '');

  // Atualiza os campos no JSON
  item.json.Nome = nome;
  item.json.telefone = telefone;
}

return $input.all();

